using System.Reflection;using System.Security.Claims;using Cfa.ACHInterbank.Api.Controllers;using Cfa.ACHInterbank.Application.Security;using Cfa.ACHInterbank.External;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;
namespace Cfa.ACHInterbank.Tests.Authorization;
public class P1MaintenancePolicyMigrationTests{[Fact]public void MaintenanceController_ComposicionAuthorizeCorrecta(){var c=typeof(MaintenanceController).GetCustomAttributes<AuthorizeAttribute>(true).ToList();Assert.Contains(c,a=>string.IsNullOrWhiteSpace(a.Policy));var ms=typeof(MaintenanceController).GetMethods(BindingFlags.Public|BindingFlags.Instance|BindingFlags.DeclaredOnly);var hs=ms.Where(m=>m.GetCustomAttribute<HttpGetAttribute>()is not null||m.GetCustomAttribute<HttpPostAttribute>()is not null||m.GetCustomAttribute<HttpPutAttribute>()is not null||m.GetCustomAttribute<HttpPatchAttribute>()is not null||m.GetCustomAttribute<HttpDeleteAttribute>()is not null).ToList();Assert.All(hs,m=>{var a=m.GetCustomAttributes<AuthorizeAttribute>(true).ToList();Assert.DoesNotContain(a,x=>x.Policy is "CanReadAch" or "CanManageAch");Assert.Contains(a,x=>x.Policy is P1Policies.MaintenanceSeed or P1Policies.MaintenanceRunAdminTask);});Assert.DoesNotContain(ms,m=>m.GetCustomAttribute<AllowAnonymousAttribute>()is not null);} [Fact]public async Task MaintenancePolicies_CompatibilidadOr(){await A(P1Policies.MaintenanceSeed,FineGrainedPermissions.Maintenance.Seed,"CanManageAch","CanReadAch");await A(P1Policies.MaintenanceRunAdminTask,FineGrainedPermissions.Maintenance.RunAdminTask,"CanManageAch","CanReadAch");}static async Task A(string pol,string fine,string ok,string bad){using var p=P();var auth=p.GetRequiredService<IAuthorizationService>();Assert.True((await auth.AuthorizeAsync(U(fine),null,pol)).Succeeded);Assert.True((await auth.AuthorizeAsync(U(ok),null,pol)).Succeeded);Assert.False((await auth.AuthorizeAsync(U(bad),null,pol)).Succeeded);Assert.False((await auth.AuthorizeAsync(new ClaimsPrincipal(new ClaimsIdentity()),null,pol)).Succeeded);}static ServiceProvider P(){var s=new ServiceCollection();var c=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"appSettings:tokenManager:issuerJwt","i"},{"appSettings:tokenManager:audienceJwt","a"},{"appSettings:tokenManager:secretKetJwt","this-is-a-test-secret-key-with-32-bytes"}}).Build();s.AddExternal(c);return s.BuildServiceProvider();}static ClaimsPrincipal U(string p)=>new(new ClaimsIdentity([new Claim("permission",p)],"t"));}
